  battleEl('bs-action').disabled=true;battleSet('bs-action','ОЖИДАНИЕ ДАННЫХ');battleSet('bs-verdict','ЗАГРУЗКА');battleSet('bs-verdict-copy',copy);battleSet('bs-score','—');
