const coinTfMs={'5m':300000,'15m':900000,'1h':3600000,'4h':14400000,'1d':86400000};
const coinDesk={symbol:'',analysis:null,request:0,loading:false,window:120,shift:0,focus:false,options:{ema21:true,ema50:true,ema200:false,levels:true,volume:true,rsi:true,divergence:true}};
WORLD_PROTOCOL_SPRITES.rocket=['.....mm.....','....mwwm....','...mwcwwm...','...mccwwm...','...mwvvwm...','...mwvvwm...','..mmwwwwmm..','.mmwwwwwwmm.','.mdmmwwmmdm.','...dgoood...','....goog....','.....g......'];
