function coinDetailPrice(value){return Number.isFinite(value)?'$'+value.toLocaleString('en-US',{maximumSignificantDigits:10}):'—';}
function coinClosedCandles(rows,tf,now=Date.now()){return (rows||[]).filter(c=>c.time+coinTfMs[tf]<=now);}
function coinSeries(rows){const closes=rows.map(c=>c.close);return {ema21:miEMA(closes,21),ema50:miEMA(closes,50),ema200:miEMA(closes,200),rsi:miRSISeries(rows)};}
function coinViewport(rows,count,shift,div,focus){
  let end=Math.max(2,rows.length-Math.max(0,shift)),start=Math.max(0,end-count);
  if(focus&&div?.found){start=Math.max(0,div.first.index-12);end=Math.min(rows.length,Math.max(start+count,div.second.index+16));if(end-start>320)start=Math.max(0,end-320);}
  return {start,end,rows:rows.slice(start,end)};
}
function coinDivergenceVisible(div,start,end){return Boolean(div?.found&&div.first.index>=start&&div.second.index<end&&div.first.index<div.second.index);}
function coinPrepareAnalysis(original){
  const inds={};MI_INTERVALS.forEach(tf=>inds[tf]=miIndicators(coinClosedCandles(marketIntelState.candles[tf],tf)));
  let score=50;[['15m',4],['1h',8],['4h',13],['1d',15]].forEach(([tf,w])=>{const ind=inds[tf];score+=ind.last>ind.ema21?w/2:-w/2;if(ind.rsi>54)score+=w/2;else if(ind.rsi<46)score-=w/2;});
  score+=inds['4h'].macd.hist>0?6:-6;const change=original.ticker.changePct;if(Number.isFinite(change))score+=change>0?Math.min(7,change*1.2):-Math.min(7,Math.abs(change)*1.2);score=Math.round(miClamp(score,0,100));
  const directions=MI_INTERVALS.map(tf=>inds[tf].rsi>=52&&inds[tf].last>=inds[tf].ema21?1:inds[tf].rsi<=48&&inds[tf].last<=inds[tf].ema21?-1:0),bull=directions.filter(n=>n===1).length,bear=directions.filter(n=>n===-1).length;
  const verdict=score>=70?{title:'ПОКУПАТЕЛИ СИЛЬНЕЕ',tone:'good',copy:'Закрытые свечи показывают перевес покупателей. Смотри реакцию у сопротивления и не пропускай риск отката.'}:score>=57?{title:'УМЕРЕННО БЫЧИЙ ФОН',tone:'good',copy:'Перевес покупателей есть, но горизонты ещё не полностью согласованы.'}:score>43?{title:'НАПРАВЛЕНИЯ РАСХОДЯТСЯ',tone:'warn',copy:'Чистого перевеса нет. Следи за границами диапазона и совпадением импульса.'}:score>30?{title:'УМЕРЕННО МЕДВЕЖИЙ ФОН',tone:'bad',copy:'Перевес продавцов есть. Проверь поддержку и восстановление импульса.'}:{title:'ПРОДАВЦЫ СИЛЬНЕЕ',tone:'bad',copy:'Закрытые свечи показывают давление продавцов. Важны реакция на поддержку и признаки ослабления импульса.'};
  return {...original,inds,score,bull,bear,confidence:Math.round(Math.max(bull,bear)/4*100),dailyTrend:miTrend(inds['1d']),verdict};
}
