  catch(error){if(request!==coinDesk.request||shared!==marketIntelState.requestId)return;marketIntelState.ticker=null;marketIntelState.candles=Object.fromEntries(MI_DATA_INTERVALS.map(tf=>[tf,[]]));marketIntelState.loadedAt=0;coinClear(symbol,'Данные '+symbol+' недоступны. Проверь тикер и нажми «Обновить».',true);}
