async function watchScan(force){
  if(watchtowerState.scanning){watchPost.pending=true;return;}watchtowerState.scanning=true;const request=++watchtowerState.requestId,list=[...watchtowerState.watchlist],button=document.getElementById('wt-scan-btn');button.disabled=true;button.textContent='ОБХОД…';battleSet('wt-scan-label','ПОЛУЧАЕМ СВЕЧИ');
  try{const output=[];let done=0;const queue=[...list];await Promise.all(Array.from({length:Math.min(3,queue.length)},async()=>{while(queue.length){const symbol=queue.shift();try{const data=await watchtowerLoadSymbol(symbol);output.push(watchAnalyze(data));}catch(error){output.push({symbol,error,score:0,stage:'inactive',direction:'neutral'});}finally{battleSet('wt-scan-label','ОБХОД '+(++done)+' / '+list.length);}}}));if(request!==watchtowerState.requestId)return;const active=output.filter(r=>watchtowerState.watchlist.includes(r.symbol));const events=watchTransitions(active,watchPost.baseline);watchPost.events=[...events.reverse(),...watchPost.events].slice(0,80);watchPost.lastAt=Date.now();watchtowerState.results=active.sort((a,b)=>b.score-a.score);worldRecordSource('scan');watchRender();
    const fresh=events.find(e=>e.stage==='confirmed'&&!watchPost.notified.has(e.id));if(fresh){watchPost.notified.add(fresh.id);if(watchPost.notified.size>200)watchPost.notified.delete(watchPost.notified.values().next().value);showNotif('success','СЛЕЖКА · '+fresh.symbol,fresh.title+' · новое событие, проверь сценарий',5000);}if(force)showNotif('success','ОБХОД ЗАВЕРШЁН',active.filter(r=>!r.error).length+' / '+list.length+' монет · '+events.length+' новых событий',2600);
  }finally{watchtowerState.scanning=false;button.disabled=false;button.textContent='СКАНИРОВАТЬ СЕЙЧАС';battleSet('wt-scan-label','ОБНОВЛЕНО · '+(watchtowerState.results.filter(r=>!r.error).length)+' / '+watchtowerState.watchlist.length);if(watchPost.pending){watchPost.pending=false;watchScan(false);}}
}
async function watchOpen(symbol,mode,tf,id){const r=watchtowerState.results.find(x=>x.symbol===symbol);if(!r||r.error)return;const selected=r.candidates.find(c=>c.id===id)||r.primary;if(mode==='decision'){battleState.symbol=symbol;showPage('battle',document.querySelector('[data-page="battle"]'));battleScan(symbol);return;}marketIntelState.symbol=symbol;showPage('marketintel',document.querySelector('[data-page="marketintel"]'));await coinScan(symbol,null,true);if(coinDesk.symbol!==symbol||!coinDesk.analysis)return;setMarketChartTF(tf||selected.tf);if(selected.div)coinFocusDivergence();}
