  toggleWatchtowerRule=function(button){const key=button.dataset.wtRule;watchtowerState.rules[key]=!watchtowerState.rules[key];watchtowerSavePrefs();watchPost.baseline.clear();watchScan(false);};
  const init=initWatchtower;initWatchtower=function(){coinScrollTop();init();if(watchPost.lastAt&&Date.now()-watchPost.lastAt>60000)watchScan(false);};
